    getPhoenixCancerHealthSchema(){
      const allPolicies = this.newPolicies || [];
      const cancerPolicies = allPolicies.filter(p => safeTrim(p?.type) === 'סרטן' && safeTrim(p?.company) === 'הפניקס');
      if(!cancerPolicies.length) return [];
      const cancerShort = this.getCancerShortHealthConfig?.();
      const catalog = this.buildPhoenixQuestionnaireCatalog();
      const picked = (cancerShort && catalog.cancer_short_under_600k) ? catalog.cancer_short_under_600k : catalog.critical_illness;
      if(!picked) return [];
      const companies = ['הפניקס'];
      const policyId = cancerPolicies[0]?.id || '';
      const schemaKey = (cancerShort && catalog.cancer_short_under_600k) ? 'phoenix_cancer_short' : 'phoenix_cancer_full';
      const q = (step) => {
        const questionnaireNos = (step.questionnaireNos || []).map(String);
        const fields = this.buildPhoenixFollowupFields(questionnaireNos, step.fields || []);
        const source = questionnaireNos.length ? `הפניקס · שאלון ${questionnaireNos.join(', ')}` : 'הפניקס · פירוט לפי הצהרת הטופס';
        return {
          key: `${schemaKey}__${step.key}`,
          text: step.text,
          companies,
          questionnaireNos,
          questionnaireSource: source,
          questionnaireLabel: questionnaireNos.length ? `שאלון ${questionnaireNos.join(', ')}` : 'פירוט משלים',
          fields: fields.length ? fields : [{ key:'details', label:'פירוט לפי הצהרת הפניקס', type:'textarea' }]
        };
      };
      return [{
        key: schemaKey,
        title: cancerShort ? 'הצהרת בריאות סרטן · הפניקס (עד 600,000 ₪)' : 'הצהרת בריאות סרטן · הפניקס',
        summary: cancerShort ? 'הצהרת בריאות מקוצרת לסרטן עד 600,000 ₪ של הפניקס.' : 'הצהרת בריאות סרטן של הפניקס. כל תשובת כן פותחת מודאל מרכזי עם שאלון ההמשך המדויק.',
        policyId,
        questions: (picked.steps || []).map(q)
      }];
    },

