    getMagdalLifeHealthSchema(){
      const companies = ['מגדל'];
      const textField = (key, label) => ({ key, label, type:'text' });
      const areaField = (key, label) => ({ key, label, type:'textarea' });
      const section = (label) => ({ type:'section', label });
      const fields = (title, prefix) => [
        section(title),
        textField(`${prefix}__diagnosis`, 'אבחנה / מצב רפואי'),
        textField(`${prefix}__date`, 'מועד אבחון / אירוע'),
        areaField(`${prefix}__treatment`, 'טיפול / תרופות / בדיקות / ניתוח'),
        areaField(`${prefix}__status`, 'מצב כיום / מגבלה / מעקב')
      ];
      const q = (key, text, title) => ({ key, text, companies, questionnaireLabel:title, questionnaireSource:`מגדל · ${title}`, fields: fields(title, key) });
      return [{
        key:'master_magdal_life_health',
        title:'הצהרת בריאות · מגדל ריסק / ריסק משכנתא',
        summary:'מנוע מקוצר למוצרי חיים של מגדל — תשובת כן פותחת מודאל פירוט ושמירה.',
        policyId:'',
        questions:[
          q('magdal_life__smoking', 'האם הנך מעשן כיום או עישנת בשנתיים האחרונות?', 'פירוט עישון'),
          q('magdal_life__alcohol_drugs', 'האם קיימת צריכת אלכוהול חריגה או שימוש בסמים / קנאביס כיום או בעבר?', 'אלכוהול / סמים'),
          q('magdal_life__meds_followup', 'האם הנך נוטל תרופות בקביעות או נמצא במעקב / בירור רפואי?', 'תרופות / בירור רפואי'),
          q('magdal_life__hospital_tests', 'האם אושפזת, נותחת, הומלץ לך ניתוח או עברת בדיקות הדמיה / בדיקות פולשניות ב־5 השנים האחרונות?', 'אשפוז / ניתוח / בדיקות'),
          q('magdal_life__disability', 'האם נקבעה לך נכות או שהוגשה בקשה לקביעת נכות / גמלה?', 'נכות / גמלה'),
          q('magdal_life__heart_bp', 'האם קיימת מחלת לב, כלי דם, הפרעות קצב או יתר לחץ דם?', 'לב / כלי דם / לחץ דם'),
          q('magdal_life__diabetes_endocrine', 'האם קיימת סוכרת, יתר שומנים בדם, בלוטת תריס או מחלה אנדוקרינית אחרת?', 'סוכרת / אנדוקרינולוגיה'),
          q('magdal_life__respiratory', 'האם קיימת מחלת ריאות או דרכי נשימה?', 'ריאות ודרכי נשימה'),
          q('magdal_life__neuro_mental', 'האם קיימת מחלה נוירולוגית, אפילפסיה, אירוע מוחי או מחלה נפשית?', 'נוירולוגיה / נפש'),
          q('magdal_life__cancer', 'האם אובחן גידול שפיר / ממאיר / טרום סרטני או מחלת סרטן?', 'גידולים / סרטן'),
          q('magdal_life__other', 'האם קיימת מחלה אחרת או מצב רפואי שלא פורט לעיל?', 'פירוט רפואי נוסף')
        ]
      }];
    },


