    buildMenoraFollowupFields(questionnaireNos=[], baseFields=[]){
      const map = this.getMenoraFollowupSchemas();
      const out = [];
      const seen = new Set();
      (questionnaireNos || []).forEach(no => {
        const schema = map[String(no)];
        if(!schema) return;
        out.push({ type:'section', label:`שאלון ${String(no)} · ${schema.title}` });
        (schema.fields || []).forEach(field => {
          const key = `${String(no)}__${field.key}`;
          if(seen.has(key)) return;
          seen.add(key);
          out.push({ ...field, key });
        });
      });
      if(Array.isArray(baseFields) && baseFields.length){
        out.push({ type:'section', label:'פירוט משלים' });
        baseFields.forEach(field => {
          const key = `base__${field.key}`;
          if(seen.has(key)) return;
          seen.add(key);
          out.push({ ...field, key });
        });
      }
      return out.length ? out : [{ key:'details', label:'פירוט', type:'textarea' }];
    },

