        '10': { title:'הפרעת קשב וריכוז / התפתחות', fields:[t('diagnosis','אבחנה'), t('diagnosisDate','מועד אבחון'), z('treatment','טיפול תרופתי / רגשי / התפתחותי'), z('function','תפקוד בלימודים/עבודה ומצב כיום'), z('docs','מסמכים / אבחונים')] },
