        '12': { title:'אנמיה', fields:[t('type','סוג האנמיה — פרט והרחב'), t('diagnosisDate','מועד גילוי האנמיה / גיל'), z('treatment','טיפול תרופתי ו/או מנות דם — שם תרופה ומינון'), yn('secondary','האם האנמיה משנית למחלה / בעיה רפואית אחרת'), t('hb','ערכי המוגלובין / HB אחרונים'), z('followup','מעקב רפואי — היכן ותדירות')] },
