      const policyId = mortPolicies[0]?.id || '';
      const companies = ['הכשרה'];
      const f = (nos, extra=[]) => this.buildHachsharaFollowupFields(nos, extra);

      const store = this.getHealthStore();
      const isShort = (store.hachsharaMortgageAmountMode || 'short') === 'short';
      const smokingShort = [{ key:'type', label:'סוג מוצר עישון (סיגריות / סיגרים / נרגילה / מקטרת / אלקטרוני)', type:'text' }, { key:'amount', label:'כמות ליום', type:'text' }, { key:'years', label:'כמה שנים מעשן / עישן', type:'text' }, { key:'quitDate', label:'אם הפסיק — מתי הפסיק', type:'text' }];
      const smokingFull = [
        { type:'section', label:'עישון נוכחי' },
        { key:'current_type', label:'סוג (סיגריות / סיגרים / נרגילה / מקטרת / אלקטרוני)', type:'multicheck', options:['סיגריות','סיגרים','נרגילה','מקטרת','סיגריה אלקטרונית'] },
        { key:'current_amount', label:'כמות ליום', type:'text' },
        { key:'current_years', label:'במשך כמה שנים', type:'text' },
        { type:'section', label:'עישון בעבר' },
        { key:'past_from', label:'משנת', type:'text' },
        { key:'past_to', label:'עד שנת', type:'text' },
        { key:'past_amount', label:'כמות ליום', type:'text' },
        { key:'past_type', label:'סוג', type:'multicheck', options:['סיגריות','סיגרים','נרגילה','מקטרת','סיגריה אלקטרונית'] },
        { key:'quitDate', label:'מאז אינני מעשן', type:'text' }
      ];
      const pendingTests = [{ key:'tests', label:'סוג הבדיקות (CT / MRI / US / ביופסיה / קולונוסקופיה / גסטרוסקופיה / ממוגרפיה / PSA / א.ק.ג / צנתור / אחר)', type:'textarea' }, { key:'date', label:'מועד / סטטוס הבדיקה', type:'text' }, { key:'result', label:'ממצא / תוצאות אם ידועות', type:'textarea' }];
      const herniaDetail = [{ key:'type', label:'סוג ומיקום הבקע / הרניה', type:'text' }, { key:'date', label:'מועד אבחון', type:'text' }, { key:'surgery', label:'האם נותח / הומלץ ניתוח', type:'textarea' }, { key:'status', label:'מצב כיום / חזרה / מגבלה', type:'textarea' }];

