        'full__lungs':'מחלת נשימה והריאות', 'full__digestive':'מחלת מערכת העיכול',
        'full__diabetes':'מחלת הפרשה פנימית, לרבות סוכרת',
        'full__mental':'מחלת נפש או הפרעת אכילה', 'full__senses':'מחלה במערכת החושים',
        'full__respiratory':'מחלת נשימה', 'full__musculoskeletal':'מחלת שלד / פרקים',
        'full__family':'מחלה אצל קרוב משפחה מדרגה ראשונה',
